    for (let k3 = 0; k3 <= 255; k3++) {
      const levels2 = spacedRamp(canvas, text, mix(seed, extreme, k3 / 255));
      if (ok(levels2)) return { levels: levels2, method: "spaced", problems: [] };
    }
    if (fallback && ok(fallback)) return { levels: [...fallback], method: "seed", problems: [] };
    for (let k3 = 0; k3 <= 255; k3++) {
      const levels2 = spacedRamp(canvas, mix(text, canvas, k3 / 255), extreme);
      if (ok(levels2)) return { levels: levels2, method: "spaced-neutral", problems: [] };
    }
    const levels = spacedRamp(canvas, text, extreme);
    return { levels, method: "unresolved", problems: graphProblems(levels, canvas, direction) };
